(6456122, 958275, 83754, '<td valign="top">I feel like there is a bit too much space to the left, but love the beak striation and feather detail in the greenwing.</td>', 'I feel like there is a bit too much space to the left, but love the beak striation and feather detail in the greenwing.', '2011-06-29 20:10:33.000000', NULL, 1),
(6456123, 958177, 83754, '<td valign="top">&lt;y vote for best in challenge.  Great shot.</td>', '<y vote for best in challenge.  Great shot.', '2011-06-29 20:16:30.000000', NULL, 1),
(6456172, 958131, 132996, '<td valign="top">I definitely love this shot. There''s so much emotion in it...her downcast eyes. I love the way her hand is positioned under her chin. The texture is fabulous and evokes a gothic feeling.</td>', 'I definitely love this shot. There''s so much emotion in it...her downcast eyes. I love the way her hand is positioned under her chin. The texture is fabulous and evokes a gothic feeling.', '2011-06-29 21:55:26.000000', NULL, 1),
(6456207, 958023, 64446, '<td valign="top">This is actually really good!!! (probably a not very useful comment but I might come back to elaborate further...)<br/>I''m back... this is an otherwise intriguing image! A great depth of field makes your mind wander along the streets and buildings, both in the foreground as well as in the background. The presence of a person knocking the door fits well with the notion of connection. The excellent contrast and level of details and textures just complete it very nicely...</td>', 'This is actually really good!!! (probably a not very useful comment but I might come back to elaborate further...)I''m back... this is an otherwise intriguing image! A great depth of field makes your mind wander along the streets and buildings, both in the foreground as well as in the background. The presence of a person knocking the door fits well with the notion of connection. The excellent contrast and level of details and textures just complete it very nicely...', '2011-06-29 22:16:12.000000', NULL, 1),
(6456208, 957724, 64446, '<td valign="top">My kind of image! Love the dramatic skies and the HDR pp.</td>', 'My kind of image! Love the dramatic skies and the HDR pp.', '2011-06-29 22:16:20.000000', NULL, 1),
(6456209, 958275, 64446, '<td valign="top">What a beautiful composition! Striking colors, focus super sharp with a nice and very contrasting bokeh in the bg. Superb image!!!</td>', 'What a beautiful composition! Striking colors, focus super sharp with a nice and very contrasting bokeh in the bg. Superb image!!!', '2011-06-29 22:16:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6456210, 958259, 64446, '<td valign="top">Love it! Lots of details on a otherwise interesting decayed building. Lithing, contrast and saturation to perfection. Great street image... makes you wonder...</td>', 'Love it! Lots of details on a otherwise interesting decayed building. Lithing, contrast and saturation to perfection. Great street image... makes you wonder...', '2011-06-29 22:16:25.000000', NULL, 1),
(6456211, 958107, 64446, '<td valign="top">Enticing image... It''s interesting how the pattern on her dress matches the building. Excellent work!</td>', 'Enticing image... It''s interesting how the pattern on her dress matches the building. Excellent work!', '2011-06-29 22:16:27.000000', NULL, 1),
(6456212, 958094, 64446, '<td valign="top">What a character! Great lighting, colors and focus. Excellent!</td>', 'What a character! Great lighting, colors and focus. Excellent!', '2011-06-29 22:16:28.000000', NULL, 1),
(6456213, 958273, 64446, '<td valign="top">A very sweet image and, if I spotted correctly, certainly an improvement from your first take. My only observation here is that the veil is covering just part of her left eye. I think it should cover the whole eye to avoid any distraction.</td>', 'A very sweet image and, if I spotted correctly, certainly an improvement from your first take. My only observation here is that the veil is covering just part of her left eye. I think it should cover the whole eye to avoid any distraction.', '2011-06-29 22:16:30.000000', NULL, 1),
(6456215, 957739, 64446, '<td valign="top">Excellent perspective. Really love these fiery colors contrasting with the deep blue sky...</td>', 'Excellent perspective. Really love these fiery colors contrasting with the deep blue sky...', '2011-06-29 22:16:35.000000', NULL, 1),
(6456266, 958186, 34171, '<td valign="top">I think this would have been a great HDR.</td>', 'I think this would have been a great HDR.', '2011-06-29 23:30:43.000000', NULL, 1),
