(6456414, 958131, 114285, '<td valign="top">I find this absolutely mesmorising, I love the grain, I know a lot of people don''t though. I really hope you win a ribbon, My only 10.</td>', 'I find this absolutely mesmorising, I love the grain, I know a lot of people don''t though. I really hope you win a ribbon, My only 10.', '2011-06-30 04:01:16.000000', NULL, 1),
(6456424, 958284, 108580, '<td valign="top">Despite the self degrading pose, (perhaps you thought it was fun, OOB?) the processing is good. Composition I feel is too central. Whatever the reason, this is a marked departure from traditional portraiture.</td>', 'Despite the self degrading pose, (perhaps you thought it was fun, OOB?) the processing is good. Composition I feel is too central. Whatever the reason, this is a marked departure from traditional portraiture.', '2011-06-30 04:41:04.000000', NULL, 1),
(6456431, 958211, 108580, '<td valign="top">Ok that''s new for DPC. Is it art with capital "F"? :)<br/>Kudo''s for being different and OOB.</td>', 'Ok that''s new for DPC. Is it art with capital "F"? :)Kudo''s for being different and OOB.', '2011-06-30 05:18:06.000000', NULL, 1),
